    fun text(language: String, key: String, vararg args: Any?): String {
        val index = languages.indexOf(language).coerceAtLeast(0)
        var value = catalog[key]?.get(index) ?: key
        args.forEachIndexed { i, arg -> value = value.replace("{" + i + "}", arg.toString()) }
        return value
    }
    fun language(context: Context): String =
        context.getSharedPreferences("app_language", Context.MODE_PRIVATE).getString("code", "zh-CN") ?: "zh-CN"
}

@Composable
fun tr(key: String, vararg args: Any?): String = UiStrings.text(LocalUiLanguage.current, key, *args)

@Composable
fun LanguagePicker(selected: String, onSelect: (String) -> Unit) {
    androidx.compose.foundation.layout.FlowRow {
        UiStrings.languages.forEachIndexed { index, code ->
            androidx.compose.material3.FilterChip(
                selected = selected == code, onClick = { onSelect(code) },
                label = { androidx.compose.material3.Text(UiStrings.labels[index]) },
            )
        }
    }
}
